// associated with this xdg_surface. The width and height must be greater
// than zero.
pub fn (proxy &XdgSurface) set_window_geometry(x i32, y i32, width i32, height i32) ! {
	proxy.conn.request(proxy.id, 8, [wayland.ArgValue(x), wayland.ArgValue(y), wayland.ArgValue(width),
		wayland.ArgValue(height)])!
}

// Maximize the surface. After requesting that the surface should be
// maximized, the compositor will respond by emitting a configure event with
// the "maximized" state and the required window geometry. The client should
// then update its content, drawing it in a maximized state, i.e. without
// shadow or other decoration outside of the window geometry. The client must
// also acknowledge the configure when committing the new content (see
// ack_configure). It is up to the compositor to decide how and where to
// maximize the surface, for example which output and what region of the
// screen should be used. If the surface was already maximized, the
// compositor will still emit a configure event with the "maximized" state.
// Note that unrelated compositor side state changes may cause configure
// events to be emitted at any time, meaning trying to match this request to
// a specific future configure event is futile.
pub fn (proxy &XdgSurface) set_maximized() ! {
	proxy.conn.request(proxy.id, 9, []wayland.ArgValue{})!
}

// Unmaximize the surface. After requesting that the surface should be
// unmaximized, the compositor will respond by emitting a configure event
// without the "maximized" state. If available, the compositor will include
// the window geometry dimensions the window had prior to being maximized in
// the configure request. The client must then update its content, drawing it
// in a regular state, i.e. potentially with shadow, etc. The client must
// also acknowledge the configure when committing the new content (see
// ack_configure). It is up to the compositor to position the surface after
// it was unmaximized; usually the position the surface had before
// maximizing, if applicable. If the surface was already not maximized, the
// compositor will still emit a configure event without the "maximized"
// state. Note that unrelated compositor side state changes may cause
// configure events to be emitted at any time, meaning trying to match this
// request to a specific future configure event is futile.
pub fn (proxy &XdgSurface) unset_maximized() ! {
	proxy.conn.request(proxy.id, 10, []wayland.ArgValue{})!
}

// Make the surface fullscreen. You can specify an output that you would
// prefer to be fullscreen. If this value is NULL, it's up to the compositor
// to choose which display will be used to map this surface. If the surface
// doesn't cover the whole output, the compositor will position the surface
// in the center of the output and compensate with black borders filling the
// rest of the output.
pub fn (proxy &XdgSurface) set_fullscreen(output ?wl.WlOutput) ! {
	output_id := if value := output { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 11, [wayland.ArgValue(wayland.ObjectRef{ id: output_id })])!
}

pub fn (proxy &XdgSurface) unset_fullscreen() ! {
	proxy.conn.request(proxy.id, 12, []wayland.ArgValue{})!
}

// Request that the compositor minimize your surface. There is no way to know
// if the surface is currently minimized, nor is there any way to unset
// minimization on this surface. If you are looking to throttle redrawing
// when minimized, please instead use the wl_surface.frame event for this, as
// this will also work with live previews on windows in Alt-Tab, Expose or
// similar compositor features.
pub fn (proxy &XdgSurface) set_minimized() ! {
	proxy.conn.request(proxy.id, 13, []wayland.ArgValue{})!
}

// xdg_surface.resize_edge: values of the xdg_surface protocol enum.
pub const xdg_surface_resize_edge_none = u32(0)
pub const xdg_surface_resize_edge_top = u32(1)
pub const xdg_surface_resize_edge_bottom = u32(2)
pub const xdg_surface_resize_edge_left = u32(4)
pub const xdg_surface_resize_edge_top_left = u32(5)
pub const xdg_surface_resize_edge_bottom_left = u32(6)
pub const xdg_surface_resize_edge_right = u32(8)
pub const xdg_surface_resize_edge_top_right = u32(9)
pub const xdg_surface_resize_edge_bottom_right = u32(10)

// xdg_surface.state: values of the xdg_surface protocol enum.
// the surface is maximized
pub const xdg_surface_state_maximized = u32(1)
// the surface is fullscreen
pub const xdg_surface_state_fullscreen = u32(2)
// the surface is being resized
pub const xdg_surface_state_resizing = u32(3)
// the surface is now activated
pub const xdg_surface_state_activated = u32(4)

// xdg_popup

// xdg_popup_desc is the wire description of xdg_popup.
pub const xdg_popup_desc = wayland.IfaceDesc{
	name:     'xdg_popup'
	version:  1
	requests: [
		wayland.MsgDesc{
			name:       'destroy'
			opcode:     0
			destructor: true
		},
	]
	events:   [
		wayland.MsgDesc{
			name:   'popup_done'
			opcode: 0
		},
	]
}

// XdgPopup is a client side proxy for xdg_popup.
// A popup surface is a short-lived, temporary surface that can be used to
// implement menus. It takes an explicit grab on the surface that will be
// dismissed when the user dismisses the popup. This can be done by the user
// clicking outside the surface, using the keyboard, or even locking the
// screen through closing the lid or a timeout. When the popup is dismissed,
// a popup_done event will be sent out, and at the same time the surface will
// be unmapped. The xdg_popup object is now inert and cannot be reactivated,
// so clients should destroy it. Explicitly destroying the xdg_popup object
// will also dismiss the popup and unmap the surface. Clients will receive
// events for all their surfaces during this grab (which is an "owner-events"
// grab in X11 parlance). This is done so that users can navigate through
// submenus and other "nested" popup windows without having to dismiss the
// topmost popup. Clients that want to dismiss the popup when another surface
// of their own is clicked should dismiss the popup using the destroy
// request. The parent surface must have either an xdg_surface or xdg_popup
// role. Specifying an xdg_popup for the parent means that the popups are
// nested, with this popup now being the topmost popup. Nested popups must be
// destroyed in the reverse order they were created in, e.g. the only popup
// you are allowed to destroy at all times is the topmost one. If there is an
// existing popup when creating a new popup, the parent must be the current
// topmost popup. A parent surface must be mapped before the new popup is
// mapped. When compositors choose to dismiss a popup, they will likely
// dismiss every nested popup as well. When a compositor dismisses popups, it
// will follow the same dismissing order as required from the client. The x
// and y arguments passed when creating the popup object specify where the
// top left of the popup should be placed, relative to the local surface
// coordinates of the parent surface. See xdg_shell.get_xdg_popup. The client
// must call wl_surface.commit on the corresponding wl_surface for the
// xdg_popup state to take effect. For a surface to be mapped by the
// compositor the client must have committed both the xdg_popup state and a
// buffer.
pub struct XdgPopup {
	wayland.Object
}

// xdg_popup_proxy wraps an object id in a XdgPopup proxy.
pub fn xdg_popup_proxy(conn &wayland.Connection, id u32) XdgPopup {
	return XdgPopup{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'xdg_popup'
		}
	}
}

// XdgPopupListener receives the events of a xdg_popup object.
pub interface XdgPopupListener {
	// The popup_done event is sent out when a popup is dismissed by the
	// compositor. The client should destroy the xdg_popup object at this point.
mut:
	popup_done(proxy XdgPopup)
}

// NoopXdgPopupListener ignores every xdg_popup event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopXdgPopupListener {}

pub fn (mut listener NoopXdgPopupListener) popup_done(_proxy XdgPopup) {
}

struct XdgPopupSink {
mut:
	proxy    XdgPopup
	listener XdgPopupListener = NoopXdgPopupListener{}
}

fn (mut s XdgPopupSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			s.listener.popup_done(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives xdg_popup events.
pub fn (proxy &XdgPopup) set_listener(listener XdgPopupListener) ! {
	proxy.conn.set_sink(proxy.id, XdgPopupSink{
		proxy:    *proxy
		listener: listener
	})!
}

// This destroys the popup. Explicitly destroying the xdg_popup object will
// also dismiss the popup, and unmap the surface. If this xdg_popup is not
// the "topmost" popup, a protocol error will be sent.
pub fn (proxy &XdgPopup) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// bind_xdg_shell binds the xdg_shell global to a typed proxy.
pub fn bind_xdg_shell(conn &wayland.Connection, global wayland.Global) !XdgShell {
	version := if global.version < xdg_shell_desc.version {
		global.version
	} else {
		xdg_shell_desc.version
	}
	object := conn.bind_global(global, 'xdg_shell', version, &xdg_shell_desc)!
	return XdgShell{
		Object: object
	}
}
